#ifdef _REENT
static	mutex_t malloc_mutex = MUTEX_INITIALIZER;
#endif
#endif

/* not currently reentrant on mini-os */
#define malloc_lock()
#define malloc_unlock()

static void morecore(int);
#ifdef MSTATS
void mstats(const char *);
