void
rumpuser_dprintf(const char *fmt, ...)
{
	char *buf;
	va_list va;

	buf = (void *)minios_alloc_pages(0);
	if (!buf)
		return;

	va_start(va, fmt);
	vsnprintf(buf, PAGE_SIZE, fmt, va);
	va_end(va);
	minios_console_print(NULL, buf, strlen(buf));

	minios_free_pages(buf, 0);
}

static struct {
	const char *name;
