static void *
corealloc(int shift)
{
	void *v;

#ifdef MEMALLOC_TESTING
	v = malloc((1<<shift) * pagesz);
#else
	v = (void *)minios_alloc_pages(shift);
#endif

	return v;
}

/*
 * Allocate more memory to the indicated bucket.
 */
static void
morecore(int bucket)
{
  	union overhead *op;
	long sz;		/* size of desired block */
  	long amt;			/* amount to allocate */
  	long nblks;			/* how many blocks we get */

	if (bucket < pagebucket) {
		amt = 0;
  		nblks = pagesz / (1<<(bucket + MINSHIFT));
		sz = pagesz / nblks;
	} else {
		amt = bucket - pagebucket;
		nblks = 1;
		sz = 0; /* dummy */
	}
	op = (void *)corealloc(amt);
	/* no more room! */
  	if (op == NULL)
  		return;
	/*
	 * Add new memory allocated to that on
	 * free list for this hash bucket.
	 */
  	nextf[bucket] = op;
  	while (--nblks > 0) {
		op->ov_next =
		    (union overhead *)(void *)((char *)(void *)op+(size_t)sz);
		op = op->ov_next;
  	}
	op->ov_next = NULL;
}

void
memfree(void *cp)
{   
	long size;
	union overhead *op;
	u_long alignpad;
	void *origp;

  	if (cp == NULL)
  		return;
	op = ((union overhead *)cp)-1;
	if (op->ov_magic != MAGIC) {
#ifdef MEMALLOC_TESTING
		ASSERT(0);
#endif
		return;				/* sanity */
	}

#ifdef RCHECK
  	ASSERT(op->ov_rmagic == RMAGIC);
	ASSERT(*(u_short *)((char *)(op + 1) + op->ov_size) == RMAGIC);
#endif
  	size = op->ov_index;
	alignpad = op->ov_alignpad;
  	ASSERT(size < NBUCKETS);

	malloc_lock();
	origp = (uint8_t *)cp - alignpad;

#ifdef MEMALLOC_TESTING
	{
		u_long i;

		for (i = 0; (uint8_t *)origp + i < (uint8_t *)op; i++) {
			ASSERT(*((uint8_t *)origp + i) == MAGIC);

		}
	}
#endif

	op = (void *)origp;
	op->ov_next = nextf[(unsigned int)size];/* also clobbers ov_magic */
  	nextf[(unsigned int)size] = op;
#ifdef MSTATS
  	nmalloc[(size_t)size]--;
#endif

	malloc_unlock();
}

#ifndef MEMALLOC_TESTING
void
free(void *cp)
{

	memfree(cp);
}
#endif

/*
 * don't do any of "storage compaction" nonsense, "just" the three modes:
 *   + cp == NULL ==> malloc
 *   + nbytes == 0 ==> free
 *   + else ==> realloc
 */
void *
memrealloc(void *cp, size_t nbytes)
{   
	union overhead *op;
  	size_t size;
	size_t alignpad;
	void *np;

	if (cp == NULL)
		return memalloc(nbytes, MINALIGN);

	if (nbytes == 0) {
		memfree(cp);
		return NULL;
	}

	op = ((union overhead *)cp)-1;
  	size = op->ov_index;
	alignpad = op->ov_alignpad;

	/* don't bother "compacting".  don't like it?  don't use realloc! */
	if (((1<<(size+MINSHIFT)) - (alignpad+sizeof(*op))) >= nbytes)
		return cp;

	/* we're gonna need a bigger bucket */
	np = memalloc(nbytes, MINALIGN);
	if (np == NULL)
		return NULL;

	memcpy(np, cp, (1<<(size+MINSHIFT)) - (alignpad+sizeof(*op)));
	memfree(cp);
	return np;
}

#ifndef MEMALLOC_TESTING
void *
realloc(void *cp, size_t nbytes)
{

	return memrealloc(cp, nbytes);
}
#endif

#ifdef MSTATS
/*
 * mstats - print out statistics about malloc
 * 
 * Prints two lines of numbers, one showing the length of the free list
 * for each size category, the second showing the number of mallocs -
 * frees for each size category.
 */
void
mstats(const char *s)
{
  	int i, j;
  	union overhead *p;
  	int totfree = 0,
  	totused = 0;

  	fprintf(stderr, "Memory allocation statistics %s\nfree:\t", s);
  	for (i = 0; i < NBUCKETS; i++) {
  		for (j = 0, p = nextf[i]; p; p = p->ov_next, j++)
  			;
  		fprintf(stderr, " %d", j);
  		totfree += j * (1 << (i + 3));
  	}
  	fprintf(stderr, "\nused:\t");
  	for (i = 0; i < NBUCKETS; i++) {
  		fprintf(stderr, " %d", nmalloc[i]);
  		totused += nmalloc[i] * (1 << (i + 3));
  	}
  	fprintf(stderr, "\n\tTotal in use: %d, total free: %d\n",
	    totused, totfree);
}
#endif

