static void
dofs(void)
{
	struct ufs_args ua;
	struct dirent *dent;
	DIR *dp;
	void *buf;
	int8_t *p;
	int fd;
	int rv;

	if (open("/not_there", O_RDWR) != -1 || errno != ENOENT)
		errx(1, "errno test");

	if ((rv = rump_pub_etfs_register(BLKDEV(0), "blk0",
	    RUMP_ETFS_BLK)) != 0)
		errx(1, "etfs %s", strerror(rv));

	mkdir("/mnt", 0777);
	ua.fspec = BLKDEV(0);
	if (mount(MOUNT_FFS, "/mnt", 0, &ua, sizeof(ua)) != 0)
		err(1, "mount");

