	int tests;

	printf("running demos, command line: %s\n", si->cmd_line);

	if (si->cmd_line[0]) {
		tests = si->cmd_line[0] - '0';
		if (tests < 0 || tests > 7)
			tests = 0;
	}

	if (tests & 0x1)
		dofs();
	if (tests & 0x2)
		donet();
	if (tests & 0x4)
		dohttpd();

	return 0;
}

