void dump_stack(struct thread *thread)
{
    unsigned long *bottom = (unsigned long *)(thread->stack + STACK_SIZE); 
    unsigned long *pointer = (unsigned long *)thread->thr_sp;
    int count;
    if(thread == current)
    {
#ifdef __i386__    
        asm("movl %%esp,%0"
            : "=r"(pointer));
#else
        asm("movq %%rsp,%0"
            : "=r"(pointer));
#endif
    }
    printk("The stack for \"%s\"\n", thread->name);
    for(count = 0; count < 25 && pointer < bottom; count ++)
    {
        printk("[0x%lx] 0x%lx\n", pointer, *pointer);
        pointer++;
    }

    if(pointer < bottom) printk(" ... continues.\n");
}

/* Gets run when a new thread is scheduled the first time ever, 
   defined in x86_[32/64].S */
extern void _minios_entry_thread_starter(void);

/* Pushes the specified value onto the stack of the specified thread */
static void stack_push(struct thread *thread, unsigned long value)
{
    thread->thr_sp -= sizeof(unsigned long);
    *((unsigned long *)thread->thr_sp) = value;
}

/* Architecture specific setup of thread creation */
struct thread* arch_create_thread(const char *name, void (*function)(void *),
                                  void *data, void *stack)
{
    struct thread *thread;

    thread = xmalloc(struct thread);
    /* We can't use lazy allocation here since the trap handler runs on the stack */
    if (!stack) {
        thread->stack = (char *)alloc_pages(STACK_SIZE_PAGE_ORDER);
#if 0
        printk("Thread \"%s\": pointer: 0x%lx, stack: 0x%lx\n", name, thread, 
                thread->stack);
#endif
    } else {
	thread->stack = stack;
	thread->flags |= THREAD_EXTSTACK;
    }
    thread->name = name;

    thread->thr_sp = (unsigned long)thread->stack + STACK_SIZE;
    /* Save pointer to the thread on the stack, used by current macro */
    *((unsigned long *)thread->stack) = (unsigned long)thread;

    stack_push(thread, (unsigned long) function);
    stack_push(thread, (unsigned long) data);
    thread->thr_ip = (unsigned long) _minios_entry_thread_starter;
    return thread;
}

void run_idle_thread(void)
{
    /* Switch stacks and run the thread */ 
#if defined(__i386__)
    __asm__ __volatile__("mov %0,%%esp\n\t"
                         "push %1\n\t" 
                         "ret"                                            
                         :"=m" (idle_thread->thr_sp)
                         :"m" (idle_thread->thr_ip));                          
#elif defined(__x86_64__)
    __asm__ __volatile__("mov %0,%%rsp\n\t"
                         "push %1\n\t" 
                         "ret"                                            
                         :"=m" (idle_thread->thr_sp)
                         :"m" (idle_thread->thr_ip));                                                    
#endif
}

/* Simple test for TLS support */
#ifdef __x86_64__
#include <sys/types.h>

#include <err.h>
#include <inttypes.h>
#include <pthread.h>
#include <sched.h>
#include <stdio.h>

#define NTHREADS 10
#define LOOPCNT 1000
#define IINITIAL 12345678

static __thread unsigned long c;
static __thread unsigned long i = IINITIAL;

static void *
wrkthread(void *arg)
{

	printf("Thread %d starting\n", (int)(uintptr_t)arg);
	if (i != IINITIAL) {
		printf("initial i incorrect: %lu vs. %d\n", i, IINITIAL);
		return NULL;
	}
	i++;

	while (c < LOOPCNT) {
		c++;
		sched_yield();
	}
	return (void *)(uintptr_t)c;
}

void
test_tls(void)
{
	pthread_t threads[NTHREADS];
	int n, rc;

	printf("TLS test\n");

	for (n = 0; n < NTHREADS; n++) {
		rc = pthread_create(&threads[n], NULL,
		    wrkthread, (void *)(uintptr_t)n);
		if (rc != 0) {
			errx(1, "pthread_create[%d] failed: %d", n, rc);
		}
	}

	for (n = NTHREADS-1; n >= 0; n--) {
		void *ret;
		int rv;

		rc = pthread_join(threads[n], &ret);
		if (rc != 0) {
			errx(1, "pthread_join[%d] failed: %d", n, rc);
		}
		rv = (int)(uintptr_t)ret;
		if (rv != LOOPCNT)
			errx(1, "thread[%d]: expected %d, got %d",
			    n, LOOPCNT, rv);
	}
}

#else
void test_tls(void) {}
#endif

