int
main(int argc, char *argv[])
{
	long tests;

	printf("running demos, command line: %s\n", argv[1]);

	if (argv[1]) {
		tests = strtol(argv[1], NULL, 16);
	}

	if (tests & 0x1)
		dofs();
	if (tests & 0x8)
		test_pthread();
	if (tests & 0x10)
		test_tls();
	if (tests & 0x2)
		donet();
	if (tests & 0x4)
		dohttpd();
	sleep(1);

	return 0;
}

