 * Emulate a bit of mmap.  Currently just MAP_ANON
 * and MAP_FILE+PROT_READ are supported.  For files, it's not true
 * mmap, but should cover a good deal of the cases anyway.
 */

/* for libc namespace */
#define mmap _mmap

