#define NBLKDEV 1
#define BLKFDOFF 375
static struct blkfront_dev *blkdevs[NBLKDEV];
static struct blkfront_info blkinfos[NBLKDEV];

/* TODO: refcount + close */
static int
devopen(int num)
{
	int nlocks;

	if (blkdevs[0])
		return 1;

	rumpkern_unsched(&nlocks, NULL);
	blkdevs[0] = init_blkfront(NULL, &blkinfos[0]);
	rumpkern_sched(nlocks, NULL);
	return blkdevs[0] != NULL;
}

int
rumpuser_open(const char *name, int mode, int *fdp)
{
	int acc;

	/* we support only the special case */
	if (strcmp(name, "blk0") != 0
	    || (mode & RUMPUSER_OPEN_BIO) == 0)
		return RUMP_EINVAL;

	if (!devopen(0))
		return RUMP_EPERM;

	acc = mode & RUMPUSER_OPEN_ACCMODE;
	if (acc == RUMPUSER_OPEN_WRONLY || acc == RUMPUSER_OPEN_RDWR) {
		if (blkinfos[0].mode != O_RDWR) {
			/* XXX: unopen */
			return RUMP_EROFS;
		}
	}

	*fdp = BLKFDOFF;
	return 0;
}

int
rumpuser_getfileinfo(const char *name, uint64_t *size, int *type)
{

	if (strcmp(name, "blk0") != 0)
		return RUMP_EXDEV;

	if (!devopen(0))
		return RUMP_EBADF;

	*size = blkinfos[0].sectors * blkinfos[0].sector_size;
	*type = RUMPUSER_FT_BLK;

	return 0;
}

struct biocb {
	struct blkfront_aiocb bio_aiocb;
	rump_biodone_fn bio_done;
	void *bio_arg;
	int complete;
};

static void
biocomp(struct blkfront_aiocb *aiocb, int ret)
{
	struct biocb *bio = aiocb->data;
	int nlocks;

	rumpkern_sched(0, NULL);
	if (ret)
		bio->bio_done(bio->bio_arg, 0, RUMP_EIO);
	else
		bio->bio_done(bio->bio_arg, bio->bio_aiocb.aio_nbytes, 0);
	rumpkern_unsched(&nlocks, NULL);
	bio->complete = 1;
}

void
rumpuser_bio(int fd, int op, void *data, size_t dlen, int64_t off,
	rump_biodone_fn biodone, void *donearg)
{
	struct biocb *bio = _xmalloc(sizeof(*bio), 8);
	struct blkfront_aiocb *aiocb = &bio->bio_aiocb;
	int nlocks;

	rumpkern_unsched(&nlocks, NULL);

	/* assert fd == 375 */

	bio->bio_done = biodone;
	bio->bio_arg = donearg;
	bio->complete = 0;

	aiocb->aio_dev = blkdevs[0];
	aiocb->aio_buf = data;
	aiocb->aio_nbytes = dlen;
	aiocb->aio_offset = off;
	aiocb->aio_cb = biocomp;
	aiocb->data  = bio;

	if (op & RUMPUSER_BIO_READ)
		blkfront_aio_read(aiocb);
	else
		blkfront_aio_write(aiocb);

	/* duh */
	while (!bio->complete) {
		blkfront_aio_poll(blkdevs[0]);
	}
	xfree(bio);

	rumpkern_sched(nlocks, NULL);
}

#ifndef __MINIOS_WAIT_H__
#define __MINIOS_WAIT_H__

#include <mini-os/sched.h>
#include <mini-os/os.h>
#include <mini-os/waittypes.h>

#include <sys/queue.h>

#define DEFINE_WAIT(name)                          \
struct wait_queue name = {                         \
    .thread       = get_current(),                 \
    .waiting      = 0,                             \
}


static inline void init_waitqueue_head(struct wait_queue_head *h)
{
    STAILQ_INIT(h);
}

static inline void init_waitqueue_entry(struct wait_queue *q, struct thread *thread)
{
    q->thread = thread;
    q->waiting = 0;
}

static inline void add_wait_queue(struct wait_queue_head *h, struct wait_queue *q)
{
    if (!q->waiting) {
        STAILQ_INSERT_HEAD(h, q, thread_list);
        q->waiting = 1;
    }
}

static inline void remove_wait_queue(struct wait_queue_head *h, struct wait_queue *q)
{
    if (q->waiting) {
        STAILQ_REMOVE(h, q, wait_queue, thread_list);
        q->waiting = 0;
    }
}

static inline void wake_up(struct wait_queue_head *head)
{
    unsigned long flags;
    struct wait_queue *curr, *tmp;
    local_irq_save(flags);
    STAILQ_FOREACH_SAFE(curr, head, thread_list, tmp)
         wake(curr->thread);
    local_irq_restore(flags);
}

#define add_waiter(w, wq) do {  \
    unsigned long flags;        \
    local_irq_save(flags);      \
    add_wait_queue(&wq, &w);    \
    block(get_current());       \
    local_irq_restore(flags);   \
} while (0)

#define remove_waiter(w, wq) do {  \
    unsigned long flags;           \
    local_irq_save(flags);         \
    remove_wait_queue(&wq, &w);    \
    local_irq_restore(flags);      \
} while (0)

#define wait_event_deadline(wq, condition, deadline) do {       \
    unsigned long flags;                                        \
    DEFINE_WAIT(__wait);                                        \
    if(condition)                                               \
        break;                                                  \
    for(;;)                                                     \
    {                                                           \
        /* protect the list */                                  \
        local_irq_save(flags);                                  \
        add_wait_queue(&wq, &__wait);                           \
        get_current()->wakeup_time = deadline;                  \
        clear_runnable(get_current());                          \
        local_irq_restore(flags);                               \
        if((condition) || (deadline && NOW() >= deadline))      \
            break;                                              \
        schedule();                                             \
    }                                                           \
    local_irq_save(flags);                                      \
    /* need to wake up */                                       \
    wake(get_current());                                        \
    remove_wait_queue(&wq, &__wait);                            \
    local_irq_restore(flags);                                   \
} while(0) 

#define wait_event(wq, condition) wait_event_deadline(wq, condition, 0) 



#endif /* __MINIOS_WAIT_H__ */

