static void
dofs(void)
{
	struct ufs_args ua;
	struct dirent *dent;
	DIR *dp;
	void *buf;
	int8_t *p;
	int fd;
	int rv;

	if (open("/not_there", O_RDWR) != -1 || errno != ENOENT)
		FAIL("errno test");

	if ((rv = rump_pub_etfs_register(BLKDEV, "blk0",
	    RUMP_ETFS_BLK)) != 0)
		FAIL("etfs");

	mkdir("/mnt", 0777);
	ua.fspec = BLKDEV;
	if (mount(MOUNT_FFS, "/mnt", 0, &ua, sizeof(ua)) != 0)
		FAIL("mount");

	buf = malloc(BUFSIZE);
	chdir("/mnt");

	dp = opendir(".");
	if (dp == NULL)
		err(1, "opendir");

	printk("\treading directory contents\n");
	while ((dent = readdir(dp)) != NULL) {
		printk("%d %"PRIu64" %s\n",
		    dent->d_type, dent->d_fileno, dent->d_name);
