static struct xenbus_event *remove_event(struct xenbus_event_queue *queue)
{
    struct xenbus_event *event;

    event = MINIOS_STAILQ_FIRST(&queue->events);
    if (!event)
        goto out;
    MINIOS_STAILQ_REMOVE_HEAD(&queue->events, entry);

 out:
    return event;
}

