static int
sucketonport(uint16_t port)
{
	struct sockaddr_in sin;
	int s;

	s = socket(PF_INET, SOCK_STREAM, 0);
	if (s == -1)
		err(1, "socket");

	memset(&sin, 0, sizeof(sin));
	sin.sin_len = sizeof(sin);
	sin.sin_family = AF_INET;
	sin.sin_port = htons(port);
	sin.sin_addr.s_addr = INADDR_ANY;
	if (bind(s, (struct sockaddr *)&sin, sizeof(sin)) == -1)
		err(1, "bind");

	if (listen(s, 10) == -1)
		err(1, "unix man, please listen");

	return s;
}

static void
donet(void)
{
	uint64_t zombietime;
	int rv, i;
	int s;

	setupnet();
	s = sucketonport(4096);
	ASSERT(s == 0); /* fixme */

	for (i = 0; i < MAXCONN; i++) {
		pfds[i].fd = -1;
		pfds[i].events = POLLIN;
		conns[i].c_cnt = -1;
	}
	pfds[0].fd = 0;
	maxfd = 1;

	printk("WOPR reporting for duty on port 4096\n");

	zombietime = NOW();
	for (;;) {
		if (NOW() - zombietime >= SECONDS(1)) {
			processzombies();
			zombietime = NOW();
		}

		rv = poll(pfds, maxfd, 1000);
		if (rv == 0) {
			printk("still waiting ... %lld\n", NOW());
			continue;
		}

		if (rv == -1) {
			printk("fail poll %d\n", errno);
			reboot(0, 0);
		}

		if (pfds[0].revents & POLLIN) {
			acceptconn();
			rv--;
		}

		for (i = 1; i < MAXCONN && rv; i++) {
			if (pfds[i].fd != -1 && pfds[i].revents & POLLIN) {
				readconn(i);
				rv--;
			}
		}
		ASSERT(rv == 0);
	}
}

