void
demo_thread(void *arg)
{
	start_info_t *si = arg;
	int tests;

	if (si->cmd_line[0]) {
		tests = si->cmd_line[0] - '0';
		if (tests < 0 || tests > 7)
			tests = 0;
	}

	rump_init();

	environ = the_env;
	_libc_init();

	if (tests & 0x1)
		dofs();
	if (tests & 0x2)
		donet();
	if (tests & 0x4)
		dohttpd();

	reboot(0, 0);
}

