/*
 * Submit a virtual IDT to teh hypervisor. This consists of tuples
 * (interrupt vector, privilege ring, CS:EIP of handler).
 * The 'privilege ring' field specifies the least-privileged ring that
 * can trap to that vector using a software-interrupt instruction (INT).
 */
static trap_info_t trap_table[] = {
    {  0, 0, __KERNEL_CS, (unsigned long)divide_error                },
    {  1, 0, __KERNEL_CS, (unsigned long)debug                       },
    {  3, 3, __KERNEL_CS, (unsigned long)int3                        },
    {  4, 3, __KERNEL_CS, (unsigned long)overflow                    },
    {  5, 3, __KERNEL_CS, (unsigned long)bounds                      },
    {  6, 0, __KERNEL_CS, (unsigned long)invalid_op                  },
    {  7, 0, __KERNEL_CS, (unsigned long)device_not_available        },
    {  9, 0, __KERNEL_CS, (unsigned long)coprocessor_segment_overrun },
    { 10, 0, __KERNEL_CS, (unsigned long)invalid_TSS                 },
    { 11, 0, __KERNEL_CS, (unsigned long)segment_not_present         },
    { 12, 0, __KERNEL_CS, (unsigned long)stack_segment               },
    { 13, 0, __KERNEL_CS, (unsigned long)general_protection          },
    { 14, 0, __KERNEL_CS, (unsigned long)page_fault                  },
    { 15, 0, __KERNEL_CS, (unsigned long)spurious_interrupt_bug      },
    { 16, 0, __KERNEL_CS, (unsigned long)coprocessor_error           },
    { 17, 0, __KERNEL_CS, (unsigned long)alignment_check             },
    { 19, 0, __KERNEL_CS, (unsigned long)simd_coprocessor_error      },
    {  0, 0,           0, 0                           }
};



void trap_init(void)
{
    HYPERVISOR_set_trap_table(trap_table);    
}

void trap_fini(void)
{
    HYPERVISOR_set_trap_table(NULL);
}

#!/bin/bash
set -e
outargs=()

fail () { echo >&2 "stunt ld: $*"; exit 127; }

noshift () { fail "no arg for $a"; }

echo "stunt ld: $*"

unset march
while [ $# != 0 ]; do
	a=$1; shift
	case "$a" in
	# ignore lib(s) which may be insisted upon by the toolchain
	-lssp_nonshared)
		;;
	[^-]*|-L*|-l*|--whole-archive|--no-whole-archive|--start-group|--end-group)
		outargs+=("$a")
		;;
	-m)
		march="$1"; shift || noshift
		outargs+=("$a" "$march")
		;;
	-o)
        	outfile="$1"; shift || noshift
        	;;
	-z)
		outargs+=("$a" "$1"); shift || noshift
		;;
	-pie)
		;;
	--as-needed|--no-as-needed)
		;;
	--stunt-final-script)
		finallds="$1"; shift || noshift
		;;
	--stunt-intermediate)
        	inter1="$1"; shift || noshift
        	;;
	-plugin|-plugin-opt)
		shift || noshift
		;;
	-plugin-opt=*)
		;;
	-E|--export-dynamic|--no-export-dynamic)
		;;
	*)
		fail "unknown option $a"
		;;
	esac
done

if [ x"$outfile" = x ]; then outfile=a.out; fi

set -x
ld -nostdlib -r "${outargs[@]}" -o "$inter1"
ld ${march:+-m ${march}} -T "$finallds" "$inter1" -o "$outfile"

