	for (i = 0; size >> (i + PAGE_SHIFT); i++)
		continue;

	va = alloc_contig_pages(i, 0); /* XXX: MD interface */
	*vap = (uintptr_t)va;
	*pap = virt_to_mach(va);

	return 0;
}

